//! Файл: settings/catalog/phemex.rs
//! Что делает: настройки, нужные только бирже Phemex (решение 168), — торгуемый статус пары (поле статуса в
//! документации не описано), потолок соединений WebSocket, темп сбора справочника сетей по одной монете, сколько записей
//! истории депозитов и выводов читать. Значений нет.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «Площадки и соединения»).

use super::{V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Соединений WebSocket на клиента — официально «concurrent connection limit to 5 in maximum».
const PHEMEX_CONNS_MAX: u64 = 5;
/// Группа лимитов Others — официально «100/minute».
const PHEMEX_OTHERS_PER_MIN: u64 = 100;

/// Настройки решения 168. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static PHEMEX: &[SettingDef] = &[
    d("Площадки", "venue.pair_status_listed", K::Text, L::None, "значение", V, "Решение 168, только Phemex: значение поля status пары в GET /public/products, при котором пара торгуется (поле статуса в официальной документации не описано; в примерах CCXT — «Listed») — взять из живого ответа. Пара с другим значением или без поля не торгуется ботом и не подписывается. Не задана — справочник пар Phemex не загружается (стаканов и торговли нет)"),
    d("Площадки", "venue.ws_max_conns", K::Integer, L::Positive, "соединений", V, "Решение 168, только Phemex: сколько WebSocket-соединений открывать всего (официально «Each Client has concurrent connection limit to 5 in maximum»; что такое Client — IP, ключ или UID — не сказано). Поток аккаунта (venue.balance_events) — тоже соединение. Стаканов не больше (соединений − поток) × venue.ws_symbols_per_conn (≤ 20); монеты сверх — не подписываются (запись в журнал). Не задана — стаканы Phemex не подписываются").max(PHEMEX_CONNS_MAX),
    d("Площадки", "venue.networks_requests_per_min", K::Integer, L::Positive, "запросов/мин", V, "Решение 168, только Phemex: темп фонового сбора справочника сетей — по одной монете два подписанных запроса (chainCfg и asset/info; сводного справочника нет). Группа лимитов Others — 100 запросов в минуту на пользователя, её же делят балансы, вывод, история и ставки комиссии — оставлять запас (например, 30). Не задана — справочник сетей Phemex не собирается (монеты Phemex не проходят фильтр)").max(PHEMEX_OTHERS_PER_MIN),
    d("Площадки", "venue.history_rows", K::Integer, L::Positive, "записей", V, "Решение 168, только Phemex: сколько последних записей истории депозитов и выводов читать (depositHist / withdrawHist, limit «default 20», наибольшее значение не указано; поиска по хешу или id нет). Нужно для статуса депозита по хешу, статуса вывода и поиска вывода с неизвестным итогом. Не задана — вывод с Phemex не отправляется (искать его потом нечем), статусы не читаются"),
];
